from pathlib import Path
import json
S=json.loads(Path('out/summary.json').read_text())
lines=['# curves-appb-b1: independent blind reading','','All five readings use only the supplied evidence packet. Pixel coordinates are on the original unrotated 300 dpi pages.','','Counts are **marker / trace / feature**. RMS residuals are affine diagnostics in psi / kips/in.^2; the native CSVs use the verified piecewise map.','','| Figure | Counts by series (M/T/F) | RMS x / y | By-eye x labels | By-eye y labels |','|---|---|---|---|---|']
checks={3:('0, 6, 14','7, 13, 18'),4:('0, 6, 14','0, 5, 10'),5:('0, 6, 12','5, 20, 40'),6:('0, 6, 14','5, 17, 29'),7:('0, 8, 16','0, 6, 11')}
for s in S:
 j=int(s['figure_id'][-1]);counts='; '.join(f'{sid}: {c.get("marker",0)}/{c.get("trace",0)}/{c.get("feature",0)}' for sid,c in s['counts'].items());cx,cy=checks[j];lines.append(f'| [{s["figure_id"]}]({s["figure_id"]}/notes.md) | {counts} | {s["rms_x"]:.5f} / {s["rms_y"]:.5f} | {cx} | {cy} |')
lines += ['','All affine maximum residuals are below 0.5% of the respective axis span. Each tick stub and labelled frame side is measured and independently tilted. Short stubs provide limited directional leverage: the largest affine-versus-piecewise difference over B-6 dr82 is 0.825 psi and 0.263 kips/in.^2. Per-series sensitivities are recorded in each cal-p1/calibration-sensitivity.md; the small affine RMS is not a claim of cross-plot directional precision.','','Ambiguities and reading limits:','','- FB-3: the printed y label between 7 and 9 looks like "3"; spacing confirms 8. One unresolved dense knee cluster is represented by one marker with a wide bound.','- FB-4: overlapping dense and loose circle clusters are separately recorded where residual arcs distinguish them; their bounds are widened.','- FB-5: the lower right loose circle is a partial arc; the leading zero of the loose density label is damaged.','- FB-6: the skewed frame and all ticks retain separate fitted tilts; broken/frame-overlapping circles have wider bounds.','- FB-7: dr104 is squares with x and has no polyline. The open-circle line is dr99p5 and the filled-circle line is dr77. Axis/symbol ink conceals both line origins: first-point features have 70 px bounds and traces begin at separable ink.','','Every requested sample blocked by a symbol or absent line ink is documented in trace-omissions.csv: 3, 1, 3, 0, and 6 rows for FB-3 through FB-7. These samples are omitted under rule 7, rather than placed on a symbol outline or white gap. Trace segment IDs preserve the breaks.','','Each figure directory contains:','','- cal-p1/ with calibration.json, measured anchors.csv, tick-fits.csv, verified-knots.json, line-fits.csv, all-label crops, trace ink crops, and calibration sensitivity.','- calibration-eye-checks.csv (three labels per axis).','- points-p1.csv and points-p1-native.csv, panel 1.','- overlay-p1.png at the source image dimensions.','- notes.md and trace-omissions.csv.','','validation.json records 223 rows, six eye checks per figure, 96 verified axis knots, and zero trace centers on white. input-sha256.json records the source packet hashes. Coordinate-grid crops and helper scripts are kept under out/.','','Rebuild from this workspace with the supplied Python interpreter, in this order: out/calibrate_ticks.py, out/tick_maps.py, out/refine_centers.py, out/extract.py, out/validate.py. The tools/ files are unchanged.']
Path('out/README.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
for s in S:
 d=Path('out')/s['figure_id'];p=d/'cal-p1'/'calibration-sensitivity.md';txt=p.read_text();txt=txt.replace('max |dx| (psi) | max |dy| (kips/in.^2)','max absolute dx (psi) | max absolute dy (kips/in.^2)');p.write_text(txt)
 with (d/'notes.md').open('a',encoding='utf-8') as f:f.write('\nFinal QA: enlarged trace-ink-checks.png reviewed against the source; all stored trace centers lie on dark line ink. Clean closed-circle centers were checked against their white interior extents (out/center-refinements.json); this check did not infer additional symbols.\n')
 if s['figure_id']=='FB-7':
  with (d/'notes.md').open('a',encoding='utf-8') as f:f.write('\nBoth origin features use 70 px bounds to cover concealed endpoint extents. Their trace first points are separate, visible diagonal ink; they do not assert the hidden origin location.\n')
print('Wrote out/README.md and final QA notes.')
